const escape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function localizeGuidance(html,language,lookup=translate){
 return html.replace(/lang="en"/g,`lang="${language}"`).replace(/>([^<>]+)</g,(whole,text)=>{
  const value=text.trim(),key=guidanceSource[value];return key?'>'+escape(lookup(language,key))+'<':whole;
 });
}
